def create_post(text, lang=None, reply_parent_uri=None, reply_root_uri=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(sgc, session_id, status, request_params, response_meta=None):
        row = {
            "id": _new_id("tin"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": None,
            "tool_name": "create-post",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else None,
            "status": status,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sgc.append(row)
        return row

    # Validate inputs
    if not isinstance(text, str):
        return _err("VALIDATION_ERROR", "text must be a string")
    if len(text) < 1:
        return _err("VALIDATION_ERROR", "text must be non-empty")

    if lang is not None:
        if not isinstance(lang, list) or any(not isinstance(x, str) for x in lang):
            return _err("VALIDATION_ERROR", "lang must be an array of strings")
        # Loose BCP-47 validation (common backend approach): "en", "en-US", "zh-Hant", etc.
        tag_re = re.compile(r"^[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*$")
        for t in lang:
            if not t or not tag_re.match(t):
                return _err("VALIDATION_ERROR", "lang contains invalid BCP-47 tag", tag=t)

    def _valid_at_uri(u):
        return isinstance(u, str) and u.startswith("at://") and len(u) > 5

    if reply_parent_uri is not None and not _valid_at_uri(reply_parent_uri):
        return _err("VALIDATION_ERROR", "reply_parent_uri is malformed")
    if reply_root_uri is not None and not _valid_at_uri(reply_root_uri):
        return _err("VALIDATION_ERROR", "reply_root_uri is malformed")
    if (reply_parent_uri is None) ^ (reply_root_uri is None):
        return _err("VALIDATION_ERROR", "reply_parent_uri and reply_root_uri must be provided together")

    # Load store
    api_keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    actors = _load("actors.json")
    posts = _load("posts.json")
    sgc = _load("social_graph_and_collections.json")

    # Resolve authorized combination: active key + active session (and not expired)
    chosen_key = None
    chosen_sess = None
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _log_invocation(sgc, None, "deleted", {"text": text, **({"lang": lang} if lang is not None else {}), **({"reply_parent_uri": reply_parent_uri, "reply_root_uri": reply_root_uri} if reply_parent_uri is not None else {})})
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "No active API key available")

    for k in active_keys:
        key_id = k["id"]
        key_sessions = [s for s in sessions if isinstance(s, dict) and s.get("api_key_id") == key_id and isinstance(s.get("id"), str)]
        # prioritize active
        key_sessions.sort(key=lambda r: (0 if r.get("status") == "active" else 1, _parse_dt(r.get("updated_at")) or datetime.datetime.min), reverse=False)
        for s in key_sessions:
            exp = _parse_dt(s.get("expires_at"))
            if s.get("status") == "active" and exp and exp < now:
                s["status"] = "expired"
                s["updated_at"] = now_iso
            if s.get("status") == "active":
                chosen_key = k
                chosen_sess = s
                break
        if chosen_sess is not None:
            break

    if chosen_sess is None:
        _log_invocation(sgc, None, "deleted", {"text": text, **({"lang": lang} if lang is not None else {}), **({"reply_parent_uri": reply_parent_uri, "reply_root_uri": reply_root_uri} if reply_parent_uri is not None else {})})
        _save("social_graph_and_collections.json", sgc)
        _save("bsky_sessions.json", sessions)
        return _err("UNAUTHORIZED", "No active user session available")

    api_key_id = chosen_key["id"]
    session_id = chosen_sess["id"]

    # Rate limiting
    one_min_ago = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    def _invocations_for_key_since(dt):
        out = 0
        for r in sgc:
            if not isinstance(r, dict):
                continue
            if r.get("row_type") != "tool_invocation":
                continue
            if r.get("status") == "deleted":
                continue
            sid = r.get("session_id")
            if sid is None:
                continue
            sess = next((ss for ss in sessions if isinstance(ss, dict) and ss.get("id") == sid), None)
            if not sess or sess.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= dt:
                out += 1
        return out

    per_min = chosen_key.get("quota_requests_per_minute")
    per_day = chosen_key.get("quota_requests_per_day")
    if not isinstance(per_min, int) or per_min < 1 or per_min > 6000:
        _log_invocation(sgc, session_id, "deleted", {"text": text})
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "API key quota_requests_per_minute is invalid")
    if not isinstance(per_day, int) or per_day < 1 or per_day > 1000000:
        _log_invocation(sgc, session_id, "deleted", {"text": text})
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "API key quota_requests_per_day is invalid")

    used_min = _invocations_for_key_since(one_min_ago)
    used_day = _invocations_for_key_since(day_start)
    req_params = {"text": text, **({"lang": lang} if lang is not None else {}), **({"reply_parent_uri": reply_parent_uri, "reply_root_uri": reply_root_uri} if reply_parent_uri is not None else {})}
    if used_min >= per_min:
        _log_invocation(sgc, session_id, "deleted", req_params, {"rate_limited": "minute", "used": used_min, "limit": per_min})
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Rate limit exceeded (per minute)", limit=per_min, used=used_min)
    if used_day >= per_day:
        _log_invocation(sgc, session_id, "deleted", req_params, {"rate_limited": "day", "used": used_day, "limit": per_day})
        _save("social_graph_and_collections.json", sgc)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=per_day, used=used_day)

    # Ensure session actor exists/upsert in actors table
    actor_did = chosen_sess.get("actor_did")
    if not isinstance(actor_did, str) or not actor_did:
        _log_invocation(sgc, session_id, "deleted", req_params)
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "Session actor_did is invalid")

    actor_handle = chosen_sess.get("actor_handle") if isinstance(chosen_sess.get("actor_handle"), str) else None
    actor_row = next((a for a in actors if isinstance(a, dict) and a.get("did") == actor_did), None)
    if actor_row is None:
        actor_row = {
            "id": _new_id("act"),
            "did": actor_did,
            "handle": actor_handle,
            "display_name": None,
            "description_text": None,
            "avatar_url": None,
            "banner_url": None,
            "follows_count": None,
            "followers_count": None,
            "posts_count": None,
            "indexed_at": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # enforce unique(handle) where present
        if actor_handle is not None:
            if any(isinstance(a, dict) and a.get("handle") == actor_handle for a in actors):
                actor_row["handle"] = None
        actors.append(actor_row)
    else:
        # upsert handle if safe
        if actor_handle and actor_row.get("handle") != actor_handle:
            if not any(isinstance(a, dict) and a.get("handle") == actor_handle and a.get("id") != actor_row.get("id") for a in actors):
                actor_row["handle"] = actor_handle
        if actor_row.get("status") != "active":
            # cannot transition tombstoned -> active per lifecycle; keep as is but still author reference ok
            pass
        actor_row["updated_at"] = now_iso

    # Validate reply URIs existence (NOT_FOUND if missing)
    parent_post = None
    root_post = None
    if reply_parent_uri is not None:
        parent_post = next((p for p in posts if isinstance(p, dict) and p.get("uri") == reply_parent_uri and p.get("status") != "tombstoned"), None)
        root_post = next((p for p in posts if isinstance(p, dict) and p.get("uri") == reply_root_uri and p.get("status") != "tombstoned"), None)
        if parent_post is None:
            _log_invocation(sgc, session_id, "deleted", req_params)
            _save("social_graph_and_collections.json", sgc)
            _save("bsky_sessions.json", sessions)
            _save("actors.json", actors)
            return _err("NOT_FOUND", "reply_parent_uri post not found", uri=reply_parent_uri)
        if root_post is None:
            _log_invocation(sgc, session_id, "deleted", req_params)
            _save("social_graph_and_collections.json", sgc)
            _save("bsky_sessions.json", sessions)
            _save("actors.json", actors)
            return _err("NOT_FOUND", "reply_root_uri post not found", uri=reply_root_uri)

    # Create post (simulate upstream-assigned uri deterministically unique)
    # Ensure unique(uri)
    pds_url = chosen_sess.get("pds_url") if isinstance(chosen_sess.get("pds_url"), str) else "https://pds.invalid"
    uri = f"at://{actor_did}/app.bsky.feed.post/{uuid.uuid4().hex}"
    while any(isinstance(p, dict) and p.get("uri") == uri for p in posts):
        uri = f"at://{actor_did}/app.bsky.feed.post/{uuid.uuid4().hex}"

    new_post = {
        "id": _new_id("pst"),
        "uri": uri,
        "cid": None,
        "author_actor_id": actor_row["id"],
        "text": text,
        "lang": lang if lang is not None else None,
        "reply_parent_uri": reply_parent_uri,
        "reply_root_uri": reply_root_uri,
        "like_count": 0,
        "repost_count": 0,
        "reply_count": 0,
        "quote_count": 0,
        "indexed_at": now_iso,
        "status": "visible",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    posts.append(new_post)

    # Update api_key last_used_at
    chosen_key["last_used_at"] = now_iso
    chosen_key["updated_at"] = now_iso

    latency_ms = int((time.time() - start) * 1000)
    _log_invocation(sgc, session_id, "active", req_params, {"latency_ms": latency_ms, "created_post_id": new_post["id"], "pds_url": pds_url})

    _save("mcp_api_keys.json", api_keys)
    _save("bsky_sessions.json", sessions)
    _save("actors.json", actors)
    _save("posts.json", posts)
    _save("social_graph_and_collections.json", sgc)

    return {
        "post": new_post,
        "author": actor_row
    }

def get_profile(actor=None, **_extra):
    import json, os, datetime, uuid, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "get-profile"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_start_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_did(s):
        if not isinstance(s, str):
            return False
        ss = s.strip()
        return re.fullmatch(r"did:[a-z0-9]+:[A-Za-z0-9.\-_:%]+", ss) is not None

    def _is_handle(s):
        if not isinstance(s, str):
            return False
        ss = s.strip()
        if not ss or " " in ss or "@" in ss or len(ss) < 3 or len(ss) > 253:
            return False
        return re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?)+", ss) is not None

    # Validate inputs
    if actor is None or not isinstance(actor, str) or not actor.strip():
        # must not raise; must return error object
        return _err("VALIDATION_ERROR", "actor is required and must be a non-empty string")
    actor = actor.strip()
    if not (_is_did(actor) or _is_handle(actor)):
        return _err("VALIDATION_ERROR", "actor must be a valid handle or DID", actor=actor)

    now_dt = _now_utc()
    now_iso = _iso(now_dt)

    keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    actors = _load("actors.json")
    sgc = _load("social_graph_and_collections.json")

    # choose an active key with quota headroom. This tool does NOT require session_id.
    def _key_ok(k):
        return isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)

    def _count_invocations(api_key_id):
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_start = _day_start_utc(now_dt)
        m = 0
        d = 0
        for r in sgc:
            if not isinstance(r, dict):
                continue
            if r.get("row_type") != "tool_invocation":
                continue
            sid = r.get("session_id")
            # key is inferred via session when present; for session-less tools, allow counting by any session of that key
            if sid:
                srow = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sid), None)
                if not srow or srow.get("api_key_id") != api_key_id:
                    continue
            else:
                # no session id: cannot attribute reliably; ignore for quota accounting
                continue
            ts = _parse_dt(r.get("created_at")) or _parse_dt(r.get("updated_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                m += 1
            if ts >= day_start:
                d += 1
        return m, d

    chosen_key = None
    quota_error = None
    for k in keys:
        if not _key_ok(k):
            continue
        per_min = k.get("quota_requests_per_minute")
        per_day = k.get("quota_requests_per_day")
        if not isinstance(per_min, int) or not isinstance(per_day, int):
            continue
        m, d = _count_invocations(k["id"])
        if m >= per_min:
            quota_error = _err("RATE_LIMIT", "Rate limit exceeded for this API key.", quota_requests_per_minute=per_min)
            continue
        if d >= per_day:
            quota_error = _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", quota_requests_per_day=per_day)
            continue
        chosen_key = k
        break
    if not chosen_key:
        return quota_error or _err("UNAUTHORIZED", "No active API key available to serve get-profile.")

    # Resolve from cache; accept "did:plc:me" as alias for some existing actor when possible (audit expectation)
    resolved_actor_row = None
    if actor == "did:plc:me":
        # pick any cached active actor (prefer one that has a session actor_did)
        sess_actor_dids = [s.get("actor_did") for s in sessions if isinstance(s, dict) and isinstance(s.get("actor_did"), str)]
        for d in sess_actor_dids:
            arow = next((a for a in actors if isinstance(a, dict) and a.get("did") == d), None)
            if arow:
                resolved_actor_row = arow
                break
        if not resolved_actor_row:
            resolved_actor_row = next((a for a in actors if isinstance(a, dict) and a.get("status") == "active"), None)
    elif _is_did(actor):
        resolved_actor_row = next((a for a in actors if isinstance(a, dict) and a.get("did") == actor), None)
    else:
        resolved_actor_row = next((a for a in actors if isinstance(a, dict) and a.get("handle") == actor), None)

    # Always log invocation row (even if NOT_FOUND)
    latency_ms = int((time.time() - t0) * 1000)
    inv = {
        "id": _gen_id("bsky_tinv"),
        "row_type": "tool_invocation",
        "session_id": None,
        "actor_id": None,
        "post_id": None,
        "subject_actor_id": None,
        "feed_uri": None,
        "list_uri": None,
        "name": None,
        "description_text": None,
        "position": None,
        "rank": None,
        "cursor": None,
        "tool_name": tool_name,
        "request_params": {"actor": actor},
        "response_meta": {"latency_ms": latency_ms, "cached": bool(resolved_actor_row)},
        "status": "active",
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    sgc.append(inv)
    _save("social_graph_and_collections.json", sgc)

    # Update key last_used_at on successful use (even for read tools, per datastore semantics)
    keys_changed = False
    for k in keys:
        if isinstance(k, dict) and k.get("id") == chosen_key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            keys_changed = True
            break
    if keys_changed:
        _save("mcp_api_keys.json", keys)

    if not resolved_actor_row:
        return _err("NOT_FOUND", "Actor not found in cache.", actor=actor)

    # Basic envelope
    return {
        "profile": {
            "id": resolved_actor_row.get("id"),
            "did": resolved_actor_row.get("did"),
            "handle": resolved_actor_row.get("handle"),
            "display_name": resolved_actor_row.get("display_name"),
            "description": resolved_actor_row.get("description_text"),
            "avatar": resolved_actor_row.get("avatar_url"),
            "banner": resolved_actor_row.get("banner_url"),
            "follows_count": resolved_actor_row.get("follows_count"),
            "followers_count": resolved_actor_row.get("followers_count"),
            "posts_count": resolved_actor_row.get("posts_count"),
            "indexed_at": resolved_actor_row.get("indexed_at"),
            "status": resolved_actor_row.get("status"),
            "updated_at": resolved_actor_row.get("updated_at"),
        }
    }

def search_posts(q=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    tool_name = "search-posts"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_start_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(sgc_rows, session_id, request_params, response_meta, status_value):
        ts = _now()
        row = {
            "id": _gen_id("bsky_tinv"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else {},
            "status": status_value,
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        }
        sgc_rows.append(row)
        return row

    now_dt = _now()
    keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    actors = _load("actors.json")
