    sgc = _load("social_graph_and_collections.json")
    if not isinstance(keys, list): keys = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(actors, list): actors = []
    if not isinstance(posts, list): posts = []
    if not isinstance(sgc, list): sgc = []

    # Validate inputs (accept non-string q by coercing, per audit: q=300 should not be rejected)
    if q is None:
        _log_invocation(sgc, None, {"q": q, "limit": limit, "cursor": cursor, "sort": sort}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "q is required.", field="q")
    if isinstance(q, str):
        qn = q.strip()
    else:
        qn = str(q).strip()
    if not qn:
        _log_invocation(sgc, None, {"q": q, "limit": limit, "cursor": cursor, "sort": sort}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "q must be non-empty.", field="q")

    if limit is None:
        limit_n = 25
    else:
        if not isinstance(limit, int):
            _log_invocation(sgc, None, {"q": qn, "limit": limit, "cursor": cursor, "sort": sort}, {"error": "VALIDATION_ERROR"}, "deleted")
            _save("social_graph_and_collections.json", sgc)
            return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
        if limit < 1 or limit > 100:
            _log_invocation(sgc, None, {"q": qn, "limit": limit, "cursor": cursor, "sort": sort}, {"error": "VALIDATION_ERROR"}, "deleted")
            _save("social_graph_and_collections.json", sgc)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")
        limit_n = limit

    if cursor is not None and not isinstance(cursor, str):
        _log_invocation(sgc, None, {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    if sort is None:
        sort_n = "top"
    else:
        if not isinstance(sort, str):
            _log_invocation(sgc, None, {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort}, {"error": "VALIDATION_ERROR"}, "deleted")
            _save("social_graph_and_collections.json", sgc)
            return _err("VALIDATION_ERROR", "sort must be a string.", field="sort")
        sort_n = sort.strip().lower()
        if sort_n not in ("top", "latest"):
            _log_invocation(sgc, None, {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort_n}, {"error": "VALIDATION_ERROR"}, "deleted")
            _save("social_graph_and_collections.json", sgc)
            return _err("VALIDATION_ERROR", "sort must be one of: top, latest.", field="sort")

    # Authenticated tool: require active session; auto-expire if expires_at < now
    active_key_by_id = {k.get("id"): k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)}
    session = None
    api_key = None
    sessions_changed = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        st = s.get("status")
        if st == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp < now_dt:
                s["status"] = "expired"
                s["updated_at"] = _iso(now_dt)
                sessions_changed = True
                st = "expired"
        if st != "active":
            continue
        k = active_key_by_id.get(s.get("api_key_id"))
        if not k:
            continue
        session = s
        api_key = k
        break

    if sessions_changed:
        _save("bsky_sessions.json", sessions)

    if not session or not api_key:
        _log_invocation(sgc, None, {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort_n}, {"error": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "No active session available for this tool.")

    # Rate limit / daily quota by api_key_id using tool_invocation rows in sgc (attributed via session_id)
    api_key_id = api_key.get("id")
    qpm = api_key.get("quota_requests_per_minute")
    qpd = api_key.get("quota_requests_per_day")
    if not isinstance(qpm, int) or not (1 <= qpm <= 6000):
        _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort_n}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "API key quota_requests_per_minute is invalid.", field="quota_requests_per_minute")
    if not isinstance(qpd, int) or not (1 <= qpd <= 1000000):
        _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort_n}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "API key quota_requests_per_day is invalid.", field="quota_requests_per_day")

    minute_ago = now_dt - datetime.timedelta(seconds=60)
    day_start = _day_start_utc(now_dt)
    inv_min = 0
    inv_day = 0
    for r in sgc:
        if not isinstance(r, dict) or r.get("row_type") != "tool_invocation":
            continue
        if r.get("session_id") != session.get("id"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        if ts >= minute_ago:
            inv_min += 1
        if ts >= day_start:
            inv_day += 1

    if inv_min >= qpm:
        _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort_n}, {"error": "RATE_LIMIT"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Per-minute request rate limit exceeded.", quota_requests_per_minute=qpm)
    if inv_day >= qpd:
        _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort_n}, {"error": "QUOTA_EXCEEDED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_requests_per_day=qpd)

    # Cache model: create search_query row, then compute hits from cached posts (offline)
    qhash = hashlib.sha256((qn + "|" + sort_n).encode("utf-8")).hexdigest()[:16]
    search_cursor = cursor if isinstance(cursor, str) and cursor else None

    search_query_row = {
        "id": _gen_id("bsky_squery"),
        "row_type": "search_query",
        "session_id": session.get("id"),
        "actor_id": None,
        "post_id": None,
        "subject_actor_id": None,
        "feed_uri": None,
        "list_uri": None,
        "name": None,
        "description_text": qn,
        "position": None,
        "rank": None,
        "cursor": search_cursor,
        "tool_name": None,
        "request_params": {"q": qn, "sort": sort_n, "limit": limit_n, "cursor": cursor},
        "response_meta": None,
        "status": "active",
        "created_at": _iso(now_dt),
        "updated_at": _iso(now_dt),
    }
    sgc.append(search_query_row)

    # Find matching visible posts
    qlow = qn.lower()
    matched = []
    for p in posts:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "visible":
            continue
        txt = p.get("text")
        if not isinstance(txt, str):
            continue
        if qlow in txt.lower():
            matched.append(p)

    # sort
    if sort_n == "latest":
        def _p_key(p):
            dt = _parse_dt(p.get("indexed_at")) or _parse_dt(p.get("updated_at")) or _parse_dt(p.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dt
        matched.sort(key=_p_key, reverse=True)
    else:
        def _score(p):
            lc = p.get("like_count") if isinstance(p.get("like_count"), int) else 0
            rc = p.get("repost_count") if isinstance(p.get("repost_count"), int) else 0
            qc = p.get("quote_count") if isinstance(p.get("quote_count"), int) else 0
            repc = p.get("reply_count") if isinstance(p.get("reply_count"), int) else 0
            return (lc * 3) + (rc * 2) + qc + repc
        matched.sort(key=lambda p: (_score(p), p.get("id", "")), reverse=True)

    # Cursor pagination: cursor is treated as offset integer string when provided
    offset = 0
    if search_cursor:
        try:
            offset = int(search_cursor)
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    page = matched[offset: offset + limit_n]
    next_offset = offset + len(page)
    has_more = next_offset < len(matched)
    next_cursor = str(next_offset) if has_more else None

    # Add search hit rows for returned page (cache)
    # Upsert-like: avoid duplicates of (row_type='search_hit_post', session_id, post_id, cursor==search_query_row.id)
    existing_hit_keys = set()
    for r in sgc:
        if not isinstance(r, dict) or r.get("row_type") != "search_hit_post":
            continue
        if r.get("session_id") != session.get("id"):
            continue
        pid = r.get("post_id")
        cur = r.get("cursor")
        if isinstance(pid, str) and isinstance(cur, str):
            existing_hit_keys.add((pid, cur))

    for idx, p in enumerate(page):
        pid = p.get("id")
        if not isinstance(pid, str):
            continue
        key = (pid, search_query_row["id"])
        if key in existing_hit_keys:
            continue
        sgc.append({
            "id": _gen_id("bsky_shit"),
            "row_type": "search_hit_post",
            "session_id": session.get("id"),
            "actor_id": None,
            "post_id": pid,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": idx,
            "rank": float(max(0, (len(page) - idx))),
            "cursor": search_query_row["id"],
            "tool_name": None,
            "request_params": None,
            "response_meta": None,
            "status": "active",
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        })

    # Log tool invocation (must be recorded)
    latency_ms = int((time.time() - start_t) * 1000)
    _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor, "sort": sort_n}, {"cached": True, "results": len(page), "latency_ms": latency_ms}, "active")
    _save("social_graph_and_collections.json", sgc)

    # update api key last_used_at
    now_iso = _iso(now_dt)
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("mcp_api_keys.json", keys)

    return {
        "posts": page,
        "meta": {"q": qn, "sort": sort_n, "limit": limit_n, "cursor": cursor, "total": len(matched), "has_more": has_more, "next_cursor": next_cursor, "cached": True},
    }

