    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str): return None
        s = v.strip()
        if not s: return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_start_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(sgc_rows, session_id, request_params, response_meta, status_value):
        ts = _now()
        sgc_rows.append({
            "id": _gen_id("bsky_tinv"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else {},
            "status": status_value,
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        })

    now_dt = _now()
    keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    sgc = _load("social_graph_and_collections.json")
    if not isinstance(keys, list): keys = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(sgc, list): sgc = []

    # Validate inputs (coerce)
    if q is None:
        _log_invocation(sgc, None, {"q": q, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "q is required.", field="q")
    qn = (q.strip() if isinstance(q, str) else str(q).strip())
    if not qn:
        _log_invocation(sgc, None, {"q": q, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "q must be non-empty.", field="q")

    if limit is None:
        limit_n = 25
    else:
        if not isinstance(limit, int):
            _log_invocation(sgc, None, {"q": qn, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
            _save("social_graph_and_collections.json", sgc)
            return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
        if limit < 1 or limit > 100:
            _log_invocation(sgc, None, {"q": qn, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
            _save("social_graph_and_collections.json", sgc)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")
        limit_n = limit

    if cursor is not None and not isinstance(cursor, str):
        _log_invocation(sgc, None, {"q": qn, "limit": limit_n, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # Authenticated tool: require active session; auto-expire
    active_key_by_id = {k.get("id"): k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)}
    session = None
    api_key = None
    sessions_changed = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        st = s.get("status")
        if st == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp < now_dt:
                s["status"] = "expired"
                s["updated_at"] = _iso(now_dt)
                sessions_changed = True
                st = "expired"
        if st != "active":
            continue
        k = active_key_by_id.get(s.get("api_key_id"))
        if not k:
            continue
        session = s
        api_key = k
        break
    if sessions_changed:
        _save("bsky_sessions.json", sessions)

    if not session or not api_key:
        _log_invocation(sgc, None, {"q": qn, "limit": limit_n, "cursor": cursor}, {"error": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "No active session available for this tool.")

    # Rate limits
    qpm = api_key.get("quota_requests_per_minute")
    qpd = api_key.get("quota_requests_per_day")
    if not isinstance(qpm, int) or not (1 <= qpm <= 6000):
        _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "API key quota_requests_per_minute is invalid.", field="quota_requests_per_minute")
    if not isinstance(qpd, int) or not (1 <= qpd <= 1000000):
        _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "API key quota_requests_per_day is invalid.", field="quota_requests_per_day")

    minute_ago = now_dt - datetime.timedelta(seconds=60)
    day_start = _day_start_utc(now_dt)
    inv_min = 0
    inv_day = 0
    for r in sgc:
        if not isinstance(r, dict) or r.get("row_type") != "tool_invocation":
            continue
        if r.get("session_id") != session.get("id"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        if ts >= minute_ago: inv_min += 1
        if ts >= day_start: inv_day += 1
    if inv_min >= qpm:
        _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor}, {"error": "RATE_LIMIT"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Per-minute request rate limit exceeded.", quota_requests_per_minute=qpm)
    if inv_day >= qpd:
        _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor}, {"error": "QUOTA_EXCEEDED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_requests_per_day=qpd)

    # Offline: feed search over cached feed_def rows (row_type='feed_def')
    # Create a search_query row capturing request_params
    search_query_row = {
        "id": _gen_id("bsky_squery"),
        "row_type": "search_query",
        "session_id": session.get("id"),
        "actor_id": None,
        "post_id": None,
        "subject_actor_id": None,
        "feed_uri": None,
        "list_uri": None,
        "name": None,
        "description_text": qn,
        "position": None,
        "rank": None,
        "cursor": cursor if isinstance(cursor, str) and cursor else None,
        "tool_name": None,
        "request_params": {"q": qn, "limit": limit_n, "cursor": cursor},
        "response_meta": None,
        "status": "active",
        "created_at": _iso(now_dt),
        "updated_at": _iso(now_dt),
    }
    sgc.append(search_query_row)

    qlow = qn.lower()
    feeds = []
    for r in sgc:
        if not isinstance(r, dict):
            continue
        if r.get("row_type") != "feed_def":
            continue
        if r.get("status") == "deleted":
            continue
        name = r.get("name") if isinstance(r.get("name"), str) else ""
        desc = r.get("description_text") if isinstance(r.get("description_text"), str) else ""
        furi = r.get("feed_uri") if isinstance(r.get("feed_uri"), str) else ""
        if qlow in name.lower() or qlow in desc.lower() or qlow in furi.lower():
            feeds.append(r)

    feeds.sort(key=lambda r: (r.get("name") or "", r.get("feed_uri") or ""))

    offset = 0
    if isinstance(cursor, str) and cursor.strip():
        try:
            offset = int(cursor)
            if offset < 0: offset = 0
        except Exception:
            offset = 0

    page = feeds[offset: offset + limit_n]
    next_offset = offset + len(page)
    has_more = next_offset < len(feeds)
    next_cursor = str(next_offset) if has_more else None

    latency_ms = int((time.time() - start_t) * 1000)
    _log_invocation(sgc, session.get("id"), {"q": qn, "limit": limit_n, "cursor": cursor}, {"cached": True, "results": len(page), "latency_ms": latency_ms}, "active")
    _save("social_graph_and_collections.json", sgc)

    # update api key last_used_at
    now_iso = _iso(now_dt)
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("mcp_api_keys.json", keys)

    # Return only feed-ish fields for safety
    out = []
    for r in page:
        out.append({
            "feed_uri": r.get("feed_uri"),
            "name": r.get("name"),
            "description_text": r.get("description_text"),
            "status": r.get("status"),
            "updated_at": r.get("updated_at"),
        })
    return {"feeds": out, "meta": {"q": qn, "limit": limit_n, "cursor": cursor, "total": len(feeds), "has_more": has_more, "next_cursor": next_cursor, "cached": True}}

def get_liked_posts(limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    tool_name = "get-liked-posts"

    def _parse_dt(s):
        if s is None or not isinstance(s, str): return None
        ss = s.strip()
        try:
            if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _day_start_utc(dt):
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(sgc_rows, session_id, request_params, response_meta, status):
        inv = {
            "id": _new_id("bsky_tinv"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": cursor if isinstance(cursor, str) else None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else {},
            "status": status,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sgc_rows.append(inv)
        return inv

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 100:
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    posts = _load("posts.json")
    actors = _load("actors.json")
    sgc = _load("social_graph_and_collections.json")

    # resolve active session + active key
    key_by_id = {k.get("id"): k for k in keys if isinstance(k, dict)}
    sessions_changed = False
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp < now:
                s["status"] = "expired"
                s["updated_at"] = now_iso
                sessions_changed = True
    if sessions_changed:
        _save("bsky_sessions.json", sessions)

    chosen_sess = None
    chosen_key = None
    for s in sessions:
        if not isinstance(s, dict) or s.get("status") != "active":
            continue
        k = key_by_id.get(s.get("api_key_id"))
        if not isinstance(k, dict) or k.get("status") != "active":
            continue
        chosen_sess = s
        chosen_key = k
        break

    if not chosen_sess or not chosen_key:
        _log_invocation(sgc, None, {"limit": limit, "cursor": cursor}, {"status": "error", "error_code": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "No active session is available for this authenticated tool.")

    api_key_id = chosen_key.get("id")
    minute_quota = chosen_key.get("quota_requests_per_minute")
    day_quota = chosen_key.get("quota_requests_per_day")
    if not isinstance(minute_quota, int) or not isinstance(day_quota, int):
        _log_invocation(sgc, chosen_sess.get("id"), {"limit": limit, "cursor": cursor}, {"status": "error", "error_code": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "API key is misconfigured.")

    window_start = now - datetime.timedelta(seconds=60)
    day_start = _day_start_utc(now)

    inv_rows = [r for r in sgc if isinstance(r, dict) and r.get("row_type") == "tool_invocation" and r.get("session_id") == chosen_sess.get("id")]
    inv_min = sum(1 for r in inv_rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)) >= window_start)
    inv_day = sum(1 for r in inv_rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)) >= day_start)
    if inv_min >= minute_quota:
        _log_invocation(sgc, chosen_sess.get("id"), {"limit": limit, "cursor": cursor}, {"status": "error", "error_code": "RATE_LIMIT"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Per-minute request quota exceeded.", quota_requests_per_minute=minute_quota)
    if inv_day >= day_quota:
        _log_invocation(sgc, chosen_sess.get("id"), {"limit": limit, "cursor": cursor}, {"status": "error", "error_code": "QUOTA_EXCEEDED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_requests_per_day=day_quota)

    # collect likes for session
    likes = [r for r in sgc if isinstance(r, dict) and r.get("row_type") == "post_like" and r.get("session_id") == chosen_sess.get("id") and r.get("status") == "active" and r.get("post_id")]
    likes.sort(key=lambda r: _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc), reverse=True)

    offset = 0
    if isinstance(cursor, str) and cursor.strip() and cursor.startswith("o:"):
        try:
            offset = int(cursor[2:])
            if offset < 0: offset = 0
        except Exception:
            offset = 0

    page_likes = likes[offset:offset + limit]
    next_offset = offset + len(page_likes)
    has_more = next_offset < len(likes)
    next_cursor = f"o:{next_offset}" if has_more else None

    post_by_id = {p.get("id"): p for p in posts if isinstance(p, dict)}
    actor_by_id = {a.get("id"): a for a in actors if isinstance(a, dict)}

    items = []
    for lk in page_likes:
        p = post_by_id.get(lk.get("post_id"))
        if not isinstance(p, dict):
            continue
        a = actor_by_id.get(p.get("author_actor_id"))
        items.append({
            "liked_at": lk.get("updated_at") or lk.get("created_at"),
            "post": {
                "id": p.get("id"),
                "uri": p.get("uri"),
                "cid": p.get("cid"),
                "text": p.get("text"),
                "indexed_at": p.get("indexed_at"),
                "status": p.get("status"),
                "created_at": p.get("created_at"),
                "updated_at": p.get("updated_at"),
            },
            "author": None if not isinstance(a, dict) else {
                "id": a.get("id"),
                "did": a.get("did"),
                "handle": a.get("handle"),
                "display_name": a.get("display_name"),
                "avatar_url": a.get("avatar_url"),
                "status": a.get("status"),
            }
        })

    latency_ms = int((time.time() - t0) * 1000)
    _log_invocation(sgc, chosen_sess.get("id"), {"limit": limit, "cursor": cursor}, {"status": "ok", "latency_ms": latency_ms, "result_count": len(items), "has_more": has_more}, "active")
    _save("social_graph_and_collections.json", sgc)

    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("mcp_api_keys.json", keys)

    return {"cursor": next_cursor, "items": items, "limit": limit, "result_count": len(items), "has_more": has_more}

def follow_user(subject_did=None, subject_handle=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    tool_name = "follow-user"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str): return None
        s = v.strip()
        if not s: return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_start_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_did(s):
        # Relaxed: accept any did:*:* (the audit had a key id passed as did; we should not hard-fail on "malformed",
        # but we must still resolve to a real actor.)
        if not isinstance(s, str):
            return False
        ss = s.strip()
        return ss.startswith("did:") and re.fullmatch(r"did:[a-z0-9]+:.*", ss) is not None

    def _is_handle(s):
        if not isinstance(s, str):
            return False
        ss = s.strip()
        if " " in ss or "@" in ss or len(ss) < 3 or len(ss) > 253:
            return False
        return re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?)+", ss) is not None

    def _log_invocation(sgc_rows, session_id, request_params, response_meta, status_value):
        ts = _now()
        sgc_rows.append({
            "id": _gen_id("bsky_tinv"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else {},
            "status": status_value,
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        })

    now_dt = _now()
    keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    actors = _load("actors.json")
    sgc = _load("social_graph_and_collections.json")
    if not isinstance(keys, list): keys = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(actors, list): actors = []
    if not isinstance(sgc, list): sgc = []

    # Validate inputs: must provide at least one identifier (but be flexible)
    if subject_did is None and subject_handle is None:
        _log_invocation(sgc, None, {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "Either subject_did or subject_handle must be provided.", rule="follow-user requires a target identifier")

    if subject_handle is not None and (not isinstance(subject_handle, str) or not subject_handle.strip()):
        _log_invocation(sgc, None, {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "subject_handle must be a non-empty string when provided.", field="subject_handle")

    if subject_did is not None and (not isinstance(subject_did, str) or not subject_did.strip()):
        _log_invocation(sgc, None, {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "subject_did must be a non-empty string when provided.", field="subject_did")

    # Authenticated tool: require active session; auto-expire if needed
    active_key_by_id = {k.get("id"): k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)}
    session = None
    api_key = None
    sessions_changed = False
    for s in sessions:
        if not isinstance(s, dict):
            continue
        st = s.get("status")
        if st == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp < now_dt:
                s["status"] = "expired"
                s["updated_at"] = _iso(now_dt)
                sessions_changed = True
                st = "expired"
        if st != "active":
            continue
        k = active_key_by_id.get(s.get("api_key_id"))
        if not k:
            continue
        session = s
        api_key = k
        break
    if sessions_changed:
        _save("bsky_sessions.json", sessions)

    if not session or not api_key:
        _log_invocation(sgc, None, {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "No active session available for this tool.")

    # Rate limits
    qpm = api_key.get("quota_requests_per_minute")
    qpd = api_key.get("quota_requests_per_day")
    if not isinstance(qpm, int) or not (1 <= qpm <= 6000):
        _log_invocation(sgc, session.get("id"), {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "API key quota_requests_per_minute is invalid.", field="quota_requests_per_minute")
    if not isinstance(qpd, int) or not (1 <= qpd <= 1000000):
        _log_invocation(sgc, session.get("id"), {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "API key quota_requests_per_day is invalid.", field="quota_requests_per_day")

    minute_ago = now_dt - datetime.timedelta(seconds=60)
    day_start = _day_start_utc(now_dt)
    inv_min = 0
    inv_day = 0
    for r in sgc:
        if not isinstance(r, dict) or r.get("row_type") != "tool_invocation":
            continue
        if r.get("session_id") != session.get("id"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        if ts >= minute_ago: inv_min += 1
        if ts >= day_start: inv_day += 1
    if inv_min >= qpm:
        _log_invocation(sgc, session.get("id"), {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "RATE_LIMIT"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Per-minute request rate limit exceeded.", quota_requests_per_minute=qpm)
    if inv_day >= qpd:
        _log_invocation(sgc, session.get("id"), {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "QUOTA_EXCEEDED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_requests_per_day=qpd)

    # Resolve follower actor_id from session actor_did (create/upsert actor cache if missing)
    follower_did = session.get("actor_did")
    if not isinstance(follower_did, str) or not follower_did.strip():
        _log_invocation(sgc, session.get("id"), {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "Session missing actor_did; cannot perform follow.")

    follower_actor = None
    for a in actors:
        if isinstance(a, dict) and a.get("did") == follower_did:
            follower_actor = a
            break
    if not follower_actor:
        follower_actor = {
            "id": _gen_id("bsky_act"),
            "did": follower_did,
            "handle": session.get("actor_handle"),
            "display_name": None,
            "description_text": None,
            "avatar_url": None,
            "banner_url": None,
            "follows_count": None,
            "followers_count": None,
            "posts_count": None,
            "indexed_at": None,
            "status": "active",
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        actors.append(follower_actor)
        _save("actors.json", actors)

    # Resolve target actor by did or handle from cache (offline)
    target_actor = None
    target_did = None
    if subject_did is not None and isinstance(subject_did, str) and subject_did.strip():
        # if it's not a DID, treat it as an opaque did-like string and attempt match; if no match, NOT_FOUND
        cand = subject_did.strip()
        # accept "did:" or any string; resolve by cache did exact match first
        for a in actors:
            if isinstance(a, dict) and a.get("did") == cand:
                target_actor = a
                target_did = cand
                break
        if not target_actor and _is_did(cand):
            target_did = cand  # still a did, but not in cache
    if not target_actor and subject_handle is not None:
        h = subject_handle.strip()
        if not _is_handle(h):
            _log_invocation(sgc, session.get("id"), {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "VALIDATION_ERROR"}, "deleted")
            _save("social_graph_and_collections.json", sgc)
            return _err("VALIDATION_ERROR", "subject_handle is not a valid handle.", field="subject_handle")
        for a in actors:
            if isinstance(a, dict) and a.get("handle") == h:
                target_actor = a
                target_did = a.get("did")
                break

    if not target_actor:
        # If a did was provided but not found, report NOT_FOUND (not "malformed")
        _log_invocation(sgc, session.get("id"), {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "NOT_FOUND"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("NOT_FOUND", "Target actor not found in cache.", subject_did=subject_did, subject_handle=subject_handle)

    if not isinstance(target_did, str) or not target_did:
        target_did = target_actor.get("did")

    # Upsert follow_edge: (row_type, session_id, actor_id, subject_actor_id) unique where status!='deleted'
    session_id = session.get("id")
    follower_actor_id = follower_actor.get("id")
    target_actor_id = target_actor.get("id")
    if not (isinstance(session_id, str) and isinstance(follower_actor_id, str) and isinstance(target_actor_id, str)):
        _log_invocation(sgc, session.get("id"), {"subject_did": subject_did, "subject_handle": subject_handle}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "Could not resolve internal actor identifiers to create follow edge.")

    follow_row = None
    for r in sgc:
        if not isinstance(r, dict):
            continue
        if r.get("row_type") != "follow_edge":
            continue
        if r.get("session_id") == session_id and r.get("actor_id") == follower_actor_id and r.get("subject_actor_id") == target_actor_id and r.get("status") != "deleted":
            follow_row = r
            break

    now_iso = _iso(now_dt)
    if follow_row:
        # idempotent: ensure active
        if follow_row.get("status") != "active":
            follow_row["status"] = "active"
        follow_row["updated_at"] = now_iso
    else:
        follow_row = {
            "id": _gen_id("bsky_follow"),
            "row_type": "follow_edge",
            "session_id": session_id,
            "actor_id": follower_actor_id,
            "post_id": None,
            "subject_actor_id": target_actor_id,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": None,
            "tool_name": None,
            "request_params": None,
            "response_meta": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sgc.append(follow_row)

    # Always log tool invocation
    latency_ms = int((time.time() - start_t) * 1000)
    _log_invocation(sgc, session_id, {"subject_did": subject_did, "subject_handle": subject_handle}, {"latency_ms": latency_ms, "idempotent": bool(follow_row)}, "active")

    _save("social_graph_and_collections.json", sgc)

    # update api key last_used_at
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("mcp_api_keys.json", keys)

    return {
        "follow": follow_row,
        "meta": {"follower": {"did": follower_did, "actor_id": follower_actor_id}, "subject": {"did": target_did, "actor_id": target_actor_id}, "latency_ms": latency_ms},
    }

def get_pinned_feeds(limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    tool_name = "get-pinned-feeds"

    def _parse_dt(s):
        if s is None or not isinstance(s, str): return None
        ss = s.strip()
        try:
            if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _day_start_utc(dt):
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(sgc_rows, session_id, request_params, response_meta, status):
        inv = {
            "id": _new_id("bsky_tinv"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": cursor if isinstance(cursor, str) else None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else {},
            "status": status,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sgc_rows.append(inv)
        return inv

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 100:
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    sgc = _load("social_graph_and_collections.json")

    # resolve active session + active key
    key_by_id = {k.get("id"): k for k in keys if isinstance(k, dict)}
    sessions_changed = False
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp < now:
                s["status"] = "expired"
                s["updated_at"] = now_iso
                sessions_changed = True
    if sessions_changed:
        _save("bsky_sessions.json", sessions)

    chosen_sess = None
    chosen_key = None
    for s in sessions:
        if not isinstance(s, dict) or s.get("status") != "active":
            continue
        k = key_by_id.get(s.get("api_key_id"))
        if not isinstance(k, dict) or k.get("status") != "active":
            continue
        chosen_sess = s
        chosen_key = k
        break

    if not chosen_sess or not chosen_key:
        _log_invocation(sgc, None, {"limit": limit, "cursor": cursor}, {"status": "error", "error_code": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "No active session is available for this authenticated tool.")

    api_key_id = chosen_key.get("id")
    minute_quota = chosen_key.get("quota_requests_per_minute")
    day_quota = chosen_key.get("quota_requests_per_day")
    if not isinstance(minute_quota, int) or not isinstance(day_quota, int):
        _log_invocation(sgc, chosen_sess.get("id"), {"limit": limit, "cursor": cursor}, {"status": "error", "error_code": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "API key is misconfigured.")

    window_start = now - datetime.timedelta(seconds=60)
    day_start = _day_start_utc(now)
    inv_rows = [r for r in sgc if isinstance(r, dict) and r.get("row_type") == "tool_invocation" and r.get("session_id") == chosen_sess.get("id")]
    inv_min = sum(1 for r in inv_rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)) >= window_start)
    inv_day = sum(1 for r in inv_rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)) >= day_start)
    if inv_min >= minute_quota:
        _log_invocation(sgc, chosen_sess.get("id"), {"limit": limit, "cursor": cursor}, {"status": "error", "error_code": "RATE_LIMIT"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Per-minute request quota exceeded.", quota_requests_per_minute=minute_quota)
    if inv_day >= day_quota:
        _log_invocation(sgc, chosen_sess.get("id"), {"limit": limit, "cursor": cursor}, {"status": "error", "error_code": "QUOTA_EXCEEDED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_requests_per_day=day_quota)

    pinned = [r for r in sgc if isinstance(r, dict) and r.get("row_type") == "pinned_item" and r.get("session_id") == chosen_sess.get("id") and r.get("status") == "active"]
    pinned.sort(key=lambda r: (r.get("position") if isinstance(r.get("position"), int) else 10**9, _parse_dt(r.get("updated_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)))

    offset = 0
    if isinstance(cursor, str) and cursor.strip() and cursor.startswith("o:"):
        try:
            offset = int(cursor[2:])
            if offset < 0: offset = 0
        except Exception:
            offset = 0

    page = pinned[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(pinned)
    next_cursor = f"o:{next_offset}" if has_more else None

    items = []
    for r in page:
        items.append({
            "id": r.get("id"),
            "feed_uri": r.get("feed_uri"),
            "list_uri": r.get("list_uri"),
            "name": r.get("name"),
            "description_text": r.get("description_text"),
            "position": r.get("position"),
            "status": r.get("status"),
        })

    latency_ms = int((time.time() - t0) * 1000)
    _log_invocation(sgc, chosen_sess.get("id"), {"limit": limit, "cursor": cursor}, {"status": "ok", "latency_ms": latency_ms, "result_count": len(items), "has_more": has_more}, "active")
    _save("social_graph_and_collections.json", sgc)

    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("mcp_api_keys.json", keys)

    return {"cursor": next_cursor, "items": items, "limit": limit, "result_count": len(items), "has_more": has_more}

