    minute_quota = chosen_key.get("quota_requests_per_minute")
    day_quota = chosen_key.get("quota_requests_per_day")
    if not isinstance(minute_quota, int) or not isinstance(day_quota, int):
        _log_invocation(sgc, None, {"feed_uri": feed_uri, "limit": limit, "cursor": cursor}, {"status": "error", "error_code": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "API key is misconfigured.")

    window_start = now - datetime.timedelta(seconds=60)
    day_start = _day_start_utc(now)
    inv_rows = [r for r in sgc if isinstance(r, dict) and r.get("row_type") == "tool_invocation"]
    inv_min = sum(1 for r in inv_rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)) >= window_start)
    inv_day = sum(1 for r in inv_rows if (_parse_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)) >= day_start)
    if inv_min >= minute_quota:
        _log_invocation(sgc, None, {"feed_uri": feed_uri, "limit": limit, "cursor": cursor}, {"status": "error", "error_code": "RATE_LIMIT"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Per-minute request quota exceeded.", quota_requests_per_minute=minute_quota)
    if inv_day >= day_quota:
        _log_invocation(sgc, None, {"feed_uri": feed_uri, "limit": limit, "cursor": cursor}, {"status": "error", "error_code": "QUOTA_EXCEEDED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota_requests_per_day=day_quota)

    # gather membership rows (feed_item) for this feed
    feed_items = [r for r in sgc if isinstance(r, dict) and r.get("row_type") == "feed_item" and r.get("feed_uri") == feed_uri and r.get("status") == "active" and r.get("post_id")]
    feed_items.sort(key=lambda r: _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc), reverse=True)

    offset = 0
    if isinstance(cursor, str) and cursor.strip() and cursor.startswith("o:"):
        try:
            offset = int(cursor[2:])
            if offset < 0: offset = 0
        except Exception:
            offset = 0

    page_rows = feed_items[offset:offset + limit]
    next_offset = offset + len(page_rows)
    has_more = next_offset < len(feed_items)
    next_cursor = f"o:{next_offset}" if has_more else None

    post_by_id = {p.get("id"): p for p in posts if isinstance(p, dict)}
    actor_by_id = {a.get("id"): a for a in actors if isinstance(a, dict)}

    items = []
    for fr in page_rows:
        p = post_by_id.get(fr.get("post_id"))
        if not isinstance(p, dict):
            continue
        a = actor_by_id.get(p.get("author_actor_id"))
        items.append({
            "post": {
                "id": p.get("id"),
                "uri": p.get("uri"),
                "cid": p.get("cid"),
                "text": p.get("text"),
                "indexed_at": p.get("indexed_at"),
                "status": p.get("status"),
                "created_at": p.get("created_at"),
                "updated_at": p.get("updated_at"),
            },
            "author": None if not isinstance(a, dict) else {
                "id": a.get("id"),
                "did": a.get("did"),
                "handle": a.get("handle"),
                "display_name": a.get("display_name"),
                "avatar_url": a.get("avatar_url"),
                "status": a.get("status"),
            }
        })

    latency_ms = int((time.time() - t0) * 1000)
    _log_invocation(sgc, None, {"feed_uri": feed_uri, "limit": limit, "cursor": cursor}, {"status": "ok", "latency_ms": latency_ms, "result_count": len(items), "has_more": has_more}, "active")
    _save("social_graph_and_collections.json", sgc)

    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("mcp_api_keys.json", keys)

    return {
        "feed": {"uri": feed_uri, "name": feed_def.get("name"), "description_text": feed_def.get("description_text")},
        "cursor": next_cursor,
        "items": items,
        "limit": limit,
        "result_count": len(items),
        "has_more": has_more,
    }

def get_list_posts(list_uri, limit=None, cursor=None, **_extra):
    import json, os, datetime, uuid, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if not isinstance(s, str):
            return None
        ss = s[:-1] if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(api_key_id, session_id, status, tool_name, request_params, response_meta=None, latency_ms=None):
        sg = _load("social_graph_and_collections.json")
        row = {
            "id": _new_id("sgc"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else {"status": status},
            "status": status,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sg.append(row)
        _save("social_graph_and_collections.json", sg)

        if api_key_id:
            keys = _load("mcp_api_keys.json")
            changed = False
            for k in keys:
                if k.get("id") == api_key_id:
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    changed = True
                    break
            if changed:
                _save("mcp_api_keys.json", keys)

    def _authenticate_any():
        # Ambient auth: pick an active key and active session that can satisfy authenticated tools.
        keys = _load("mcp_api_keys.json")
        sessions = _load("bsky_sessions.json")

        active_keys = [k for k in keys if k.get("status") == "active" and isinstance(k.get("id"), str)]
        if not active_keys:
            return None, None, None, _err("UNAUTHORIZED", "No active API key available.")

        # Update expired sessions before selection
        sessions_changed = False
        for s in sessions:
            if s.get("status") == "active":
                exp = _parse_dt(s.get("expires_at"))
                if exp and exp < now:
                    s["status"] = "expired"
                    s["updated_at"] = now_iso
                    sessions_changed = True
        if sessions_changed:
            _save("bsky_sessions.json", sessions)

        # Find combination: active key + active session belonging to that key
        for k in active_keys:
            kid = k["id"]
            for s in sessions:
                if s.get("api_key_id") == kid and s.get("status") == "active":
                    return k, s, kid, None

        return None, None, None, _err("UNAUTHORIZED", "No valid active session available.")

    def _rate_limit_check(api_key_id):
        keys = _load("mcp_api_keys.json")
        key = next((k for k in keys if k.get("id") == api_key_id), None)
        if not key:
            return _err("UNAUTHORIZED", "API key not found.")
        if key.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active.")

        per_min = key.get("quota_requests_per_minute")
        per_day = key.get("quota_requests_per_day")
        if not isinstance(per_min, int) or not (1 <= per_min <= 6000):
            return _err("VALIDATION_ERROR", "Invalid quota_requests_per_minute on key.")
        if not isinstance(per_day, int) or not (1 <= per_day <= 1000000):
            return _err("VALIDATION_ERROR", "Invalid quota_requests_per_day on key.")

        sg = _load("social_graph_and_collections.json")
        inv = [r for r in sg if r.get("row_type") == "tool_invocation" and r.get("status") in ("active", "stale", "deleted")]
        # Limit by api_key_id via session join (tool_invocation doesn't store api_key_id)
        sessions = _load("bsky_sessions.json")
        session_ids = {s.get("id") for s in sessions if s.get("api_key_id") == api_key_id}
        # Also include invocations without session_id? Those cannot be attributed safely; ignore for this tool (requires session anyway).
        inv = [r for r in inv if r.get("session_id") in session_ids]

        minute_ago = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day)

        c_min = 0
        c_day = 0
        for r in inv:
            dt = _parse_dt(r.get("created_at"))
            if not dt:
                continue
            if dt >= day_start:
                c_day += 1
            if dt >= minute_ago:
                c_min += 1

        if c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=per_min, window_seconds=60)
        if c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=per_day, window="day")
        return None

    # Validate inputs
    if not isinstance(list_uri, str) or not list_uri.strip():
        # Need to log even validation errors; but we need auth context first for rate limits.
        key, sess, api_key_id, auth_err = _authenticate_any()
        if auth_err:
            return auth_err
        rl_err = _rate_limit_check(api_key_id)
        if rl_err:
            _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                            {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                            response_meta={"error": rl_err["error"]["code"]}, latency_ms=int((time.time()-t0)*1000))
            return rl_err
        _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                        {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                        response_meta={"error": "VALIDATION_ERROR"}, latency_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "list_uri is required.")
    if not re.match(r"^at://", list_uri):
        key, sess, api_key_id, auth_err = _authenticate_any()
        if auth_err:
            return auth_err
        rl_err = _rate_limit_check(api_key_id)
        if rl_err:
            _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                            {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                            response_meta={"error": rl_err["error"]["code"]}, latency_ms=int((time.time()-t0)*1000))
            return rl_err
        _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                        {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                        response_meta={"error": "VALIDATION_ERROR"}, latency_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "list_uri must be an AT Protocol URI starting with 'at://'.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 100):
        key, sess, api_key_id, auth_err = _authenticate_any()
        if auth_err:
            return auth_err
        rl_err = _rate_limit_check(api_key_id)
        if rl_err:
            _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                            {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                            response_meta={"error": rl_err["error"]["code"]}, latency_ms=int((time.time()-t0)*1000))
            return rl_err
        _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                        {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                        response_meta={"error": "VALIDATION_ERROR"}, latency_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.startswith("idx:"):
            key, sess, api_key_id, auth_err = _authenticate_any()
            if auth_err:
                return auth_err
            rl_err = _rate_limit_check(api_key_id)
            if rl_err:
                _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                                {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                                response_meta={"error": rl_err["error"]["code"]}, latency_ms=int((time.time()-t0)*1000))
                return rl_err
            _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                            {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                            response_meta={"error": "VALIDATION_ERROR"}, latency_ms=int((time.time()-t0)*1000))
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        try:
            start = int(cursor.split(":", 1)[1])
            if start < 0:
                raise ValueError()
        except ValueError:
            key, sess, api_key_id, auth_err = _authenticate_any()
            if auth_err:
                return auth_err
            rl_err = _rate_limit_check(api_key_id)
            if rl_err:
                _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                                {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                                response_meta={"error": rl_err["error"]["code"]}, latency_ms=int((time.time()-t0)*1000))
                return rl_err
            _log_invocation(api_key_id, sess.get("id") if sess else None, "deleted", "get-list-posts",
                            {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                            response_meta={"error": "VALIDATION_ERROR"}, latency_ms=int((time.time()-t0)*1000))
            return _err("VALIDATION_ERROR", "cursor is malformed.")
    else:
        start = 0

    # Auth + rate limit
    key, sess, api_key_id, auth_err = _authenticate_any()
    if auth_err:
        return auth_err
    rl_err = _rate_limit_check(api_key_id)
    if rl_err:
        _log_invocation(api_key_id, sess.get("id"), "deleted", "get-list-posts",
                        {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                        response_meta={"error": rl_err["error"]["code"]}, latency_ms=int((time.time()-t0)*1000))
        return rl_err

    # List must exist (resolved)
    sg = _load("social_graph_and_collections.json")
    list_def = next((r for r in sg if r.get("row_type") == "list_def" and r.get("list_uri") == list_uri and r.get("status") != "deleted"), None)
    if not list_def:
        _log_invocation(api_key_id, sess.get("id"), "deleted", "get-list-posts",
                        {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                        response_meta={"error": "NOT_FOUND"}, latency_ms=int((time.time()-t0)*1000))
        return _err("NOT_FOUND", "List not found or cannot be resolved.")

    # Fetch cached list items (membership)
    list_items = [r for r in sg if r.get("row_type") == "list_item" and r.get("list_uri") == list_uri and r.get("status") != "deleted" and r.get("post_id")]
    # Order: newest first by created_at if present, then id
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (dt, r.get("id") or "")
    list_items.sort(key=_sort_key, reverse=True)

    total = len(list_items)
    page_items = list_items[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = f"idx:{start+limit}"

    posts = _load("posts.json")
    actors = _load("actors.json")
    posts_by_id = {p.get("id"): p for p in posts if isinstance(p.get("id"), str)}
    actors_by_id = {a.get("id"): a for a in actors if isinstance(a.get("id"), str)}

    out_posts = []
    for it in page_items:
        p = posts_by_id.get(it.get("post_id"))
        if not p:
            continue
        author = actors_by_id.get(p.get("author_actor_id"))
        out_posts.append({
            "id": p.get("id"),
            "uri": p.get("uri"),
            "cid": p.get("cid"),
            "text": p.get("text"),
            "lang": p.get("lang"),
            "indexed_at": p.get("indexed_at"),
            "status": p.get("status"),
            "author": None if not author else {
                "id": author.get("id"),
                "did": author.get("did"),
                "handle": author.get("handle"),
                "display_name": author.get("display_name"),
                "avatar_url": author.get("avatar_url"),
                "status": author.get("status"),
            }
        })

    latency_ms = int((time.time() - t0) * 1000)
    _log_invocation(api_key_id, sess.get("id"), "active", "get-list-posts",
                    {"list_uri": list_uri, "limit": limit, "cursor": cursor},
                    response_meta={"cached": True, "returned": len(out_posts), "total_cached": total, "latency_ms": latency_ms},
                    latency_ms=latency_ms)

    return {
        "list_uri": list_uri,
        "posts": out_posts,
        "cursor": next_cursor,
        "meta": {"limit": limit, "total_cached": total, "has_more": next_cursor is not None}
    }

def get_user_posts(actor_did=None, actor_handle=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    tool_name = "get-user-posts"

    def _parse_dt(s):
        if s is None or not isinstance(s, str): return None
        ss = s.strip()
        try:
            if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _day_start_utc(dt):
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_did(s):
        return isinstance(s, str) and re.fullmatch(r"did:[a-z0-9]+:[A-Za-z0-9.\-_:%]+", s.strip()) is not None

    def _is_handle(s):
        if not isinstance(s, str): return False
        s = s.strip()
        if " " in s or "@" in s or len(s) < 3 or len(s) > 253:
            return False
        return re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?)+", s) is not None

    def _log_invocation(sgc_rows, session_id, request_params, response_meta, status):
        inv = {
            "id": _new_id("bsky_tinv"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": cursor if isinstance(cursor, str) else None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else {},
            "status": status,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sgc_rows.append(inv)
        return inv

    # validate (relax: allow empty args -> use session actor if available)
    if actor_did is not None and (not isinstance(actor_did, str) or not _is_did(actor_did)):
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"actor_did": actor_did, "actor_handle": actor_handle, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "actor_did is malformed.", field="actor_did")
    if actor_handle is not None and (not isinstance(actor_handle, str) or not _is_handle(actor_handle)):
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"actor_did": actor_did, "actor_handle": actor_handle, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "actor_handle is malformed.", field="actor_handle")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"actor_did": actor_did, "actor_handle": actor_handle, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 100:
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"actor_did": actor_did, "actor_handle": actor_handle, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        sgc = _load("social_graph_and_collections.json")
        _log_invocation(sgc, None, {"actor_did": actor_did, "actor_handle": actor_handle, "limit": limit, "cursor": cursor}, {"error": "VALIDATION_ERROR"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    actors = _load("actors.json")
    posts = _load("posts.json")
    sgc = _load("social_graph_and_collections.json")

    # resolve active api key for quotas (tool not specified as authenticated-only)
