def get_post_likes(post_uri, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(sgc_rows, *, tool_name, request_params, session_id, status, api_key_id, latency_ms, error_code=None):
        row = {
            "id": _gen_id("tinv"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": {
                "status": status,
                "api_key_id": api_key_id,
                "latency_ms": latency_ms,
                **({} if error_code is None else {"error_code": error_code}),
            },
            "status": "active",
            "created_at": _now(),
            "updated_at": _now(),
        }
        sgc_rows.append(row)
        return row

    t0 = time.time()

    # Validate inputs
    if not isinstance(post_uri, str) or not post_uri.strip():
        return _err("VALIDATION_ERROR", "post_uri is required and must be a non-empty string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit out of range (must be between 1 and 100)")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")

    # Cursor format: "ts:<iso>|id:<rowid>"
    cursor_ts = None
    cursor_id = None
    if cursor is not None:
        if not cursor.startswith("ts:") or "|id:" not in cursor:
            return _err("VALIDATION_ERROR", "cursor is malformed")
        try:
            ts_part, id_part = cursor.split("|id:", 1)
            cursor_ts = ts_part[3:]
            cursor_id = id_part
            if not cursor_id:
                return _err("VALIDATION_ERROR", "cursor is malformed")
            dt = _parse_dt(cursor_ts)
            if dt is None:
                return _err("VALIDATION_ERROR", "cursor is malformed")
        except ValueError:
            return _err("VALIDATION_ERROR", "cursor is malformed")

    # Load datastore
    api_keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    actors = _load("actors.json")
    posts = _load("posts.json")
    sgc = _load("social_graph_and_collections.json")

    # Resolve an active api key + active, unexpired session (authenticated tool)
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)

    active_key = None
    active_session = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        api_key_id = s.get("api_key_id")
        if not api_key_id:
            continue
        k = next((x for x in api_keys if isinstance(x, dict) and x.get("id") == api_key_id), None)
        if not k:
            continue
        if k.get("status") != "active":
            continue

        # Session must be active; if expired_at passed, transition to expired before tool use
        if s.get("status") not in ("active", "expired", "revoked"):
            continue
        exp = _parse_dt(s.get("expires_at"))
        if exp is not None and exp < now_dt and s.get("status") == "active":
            s["status"] = "expired"
            s["updated_at"] = _now()

        if s.get("status") != "active":
            continue

        active_key = k
        active_session = s
        break

    if active_key is None or active_session is None:
        # Must still log invocation attempt if we can associate an api_key; but requirement says reject when no valid session
        # With no credentials passed, if none exists, it's UNAUTHORIZED.
        # We log without api_key_id if we cannot resolve one.
        latency = int((time.time() - t0) * 1000)
        _log_invocation(
            sgc,
            tool_name="get-post-likes",
            request_params={"post_uri": post_uri, "limit": limit, "cursor": cursor} if cursor is not None else {"post_uri": post_uri, "limit": limit},
            session_id=None,
            status="error",
            api_key_id=None,
            latency_ms=latency,
            error_code="UNAUTHORIZED",
        )
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "No valid active session is available for this operation")

    api_key_id = active_key["id"]
    session_id = active_session["id"]

    # Rate limit / quota: based on tool_invocation rows in sgc
    day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
    per_min = active_key.get("quota_requests_per_minute")
    per_day = active_key.get("quota_requests_per_day")
    if not isinstance(per_min, int) or not (1 <= per_min <= 6000):
        per_min = 60
    if not isinstance(per_day, int) or not (1 <= per_day <= 1000000):
        per_day = 10000

    invocations = [
        r for r in sgc
        if isinstance(r, dict)
        and r.get("row_type") == "tool_invocation"
        and isinstance((r.get("response_meta") or {}).get("api_key_id"), str)
        and (r.get("response_meta") or {}).get("api_key_id") == api_key_id
    ]

    def _inv_dt(r):
        return _parse_dt(r.get("created_at")) or _parse_dt(r.get("updated_at"))

    last_60 = 0
    today = 0
    for r in invocations:
        dt = _inv_dt(r)
        if dt is None:
            continue
        if dt >= now_dt - datetime.timedelta(seconds=60):
            last_60 += 1
        if dt >= day_start:
            today += 1

    if last_60 >= per_min:
        latency = int((time.time() - t0) * 1000)
        _log_invocation(
            sgc,
            tool_name="get-post-likes",
            request_params={"post_uri": post_uri, "limit": limit, "cursor": cursor} if cursor is not None else {"post_uri": post_uri, "limit": limit},
            session_id=session_id,
            status="error",
            api_key_id=api_key_id,
            latency_ms=latency,
            error_code="RATE_LIMIT",
        )
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key (per-minute quota)")
    if today >= per_day:
        latency = int((time.time() - t0) * 1000)
        _log_invocation(
            sgc,
            tool_name="get-post-likes",
            request_params={"post_uri": post_uri, "limit": limit, "cursor": cursor} if cursor is not None else {"post_uri": post_uri, "limit": limit},
            session_id=session_id,
            status="error",
            api_key_id=api_key_id,
            latency_ms=latency,
            error_code="QUOTA_EXCEEDED",
        )
        _save("social_graph_and_collections.json", sgc)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key")

    # Find the post
    post_row = next((p for p in posts if isinstance(p, dict) and p.get("uri") == post_uri), None)
    if post_row is None:
        latency = int((time.time() - t0) * 1000)
        _log_invocation(
            sgc,
            tool_name="get-post-likes",
            request_params={"post_uri": post_uri, "limit": limit, "cursor": cursor} if cursor is not None else {"post_uri": post_uri, "limit": limit},
            session_id=session_id,
            status="error",
            api_key_id=api_key_id,
            latency_ms=latency,
            error_code="NOT_FOUND",
        )
        _save("social_graph_and_collections.json", sgc)
        return _err("NOT_FOUND", "Post not found")

    post_id = post_row.get("id")
    if not isinstance(post_id, str) or not post_id:
        latency = int((time.time() - t0) * 1000)
        _log_invocation(
            sgc,
            tool_name="get-post-likes",
            request_params={"post_uri": post_uri, "limit": limit, "cursor": cursor} if cursor is not None else {"post_uri": post_uri, "limit": limit},
            session_id=session_id,
            status="error",
            api_key_id=api_key_id,
            latency_ms=latency,
            error_code="NOT_FOUND",
        )
        _save("social_graph_and_collections.json", sgc)
        return _err("NOT_FOUND", "Post could not be resolved")

    # Collect active likes for this post
    like_rows = [
        r for r in sgc
        if isinstance(r, dict)
        and r.get("row_type") == "post_like"
        and r.get("post_id") == post_id
        and r.get("status") == "active"
    ]

    # Sort by created_at desc then id desc
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (dt, str(r.get("id") or ""))

    like_rows.sort(key=_sort_key, reverse=True)

    # Apply cursor
    if cursor is not None:
        cur_dt = _parse_dt(cursor_ts)
        filtered = []
        for r in like_rows:
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
            rid = str(r.get("id") or "")
            # items strictly "before" cursor in the same ordering
            if dt < cur_dt or (dt == cur_dt and rid < cursor_id):
                filtered.append(r)
        like_rows = filtered

    page = like_rows[:limit]
    has_more = len(like_rows) > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_dt(last.get("created_at")) or datetime.datetime(1970, 1, 1)
        next_cursor = f"ts:{last_dt.isoformat()}Z|id:{str(last.get('id') or '')}"

    # Join to actors via session_id -> session actor_did if available, else actor_id in like row
    # Schema for post_like uses post_id + session_id; the actor who liked is the session actor.
    session_by_id = {s.get("id"): s for s in sessions if isinstance(s, dict) and isinstance(s.get("id"), str)}
    actor_by_did = {a.get("did"): a for a in actors if isinstance(a, dict) and isinstance(a.get("did"), str)}
    actor_by_id = {a.get("id"): a for a in actors if isinstance(a, dict) and isinstance(a.get("id"), str)}

    results = []
    for lr in page:
        sid = lr.get("session_id")
        liker_actor = None
        if isinstance(sid, str) and sid in session_by_id:
            did = session_by_id[sid].get("actor_did")
            if isinstance(did, str):
                liker_actor = actor_by_did.get(did)
        if liker_actor is None:
            aid = lr.get("actor_id")
            if isinstance(aid, str):
                liker_actor = actor_by_id.get(aid)

        results.append({
            "like_id": lr.get("id"),
            "post_uri": post_uri,
            "post_id": post_id,
            "created_at": lr.get("created_at"),
            "actor": None if liker_actor is None else {
                "id": liker_actor.get("id"),
                "did": liker_actor.get("did"),
                "handle": liker_actor.get("handle"),
                "display_name": liker_actor.get("display_name"),
                "avatar_url": liker_actor.get("avatar_url"),
                "status": liker_actor.get("status"),
            }
        })

    # Update key last_used_at on success
    active_key["last_used_at"] = _now()
    active_key["updated_at"] = _now()

    latency = int((time.time() - t0) * 1000)
    _log_invocation(
        sgc,
        tool_name="get-post-likes",
        request_params={"post_uri": post_uri, "limit": limit, **({} if cursor is None else {"cursor": cursor})},
        session_id=session_id,
        status="ok",
        api_key_id=api_key_id,
        latency_ms=latency,
        error_code=None,
    )

    _save("mcp_api_keys.json", api_keys)
    _save("bsky_sessions.json", sessions)
    _save("social_graph_and_collections.json", sgc)

    return {
        "post_uri": post_uri,
        "likes": results,
        "cursor": next_cursor,
        "limit": limit,
        "meta": {
            "returned": len(results),
            "has_more": bool(has_more),
            "total_cached_active_likes": len([r for r in sgc if isinstance(r, dict) and r.get("row_type") == "post_like" and r.get("post_id") == post_id and r.get("status") == "active"]),
        }
    }

def list_resources(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0084000" if __import__("os").path.isdir("./environment_mix/0084000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    tool_name = "list-resources"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str): return None
        s = v.strip()
        if not s: return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _day_start_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(sgc_rows, session_id, request_params, response_meta, status_value):
        ts = _now()
        sgc_rows.append({
            "id": _gen_id("bsky_tinv"),
            "row_type": "tool_invocation",
            "session_id": session_id,
            "actor_id": None,
            "post_id": None,
            "subject_actor_id": None,
            "feed_uri": None,
            "list_uri": None,
            "name": None,
            "description_text": None,
            "position": None,
            "rank": None,
            "cursor": None,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_meta": response_meta if isinstance(response_meta, dict) else {},
            "status": status_value,
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        })

    now_dt = _now()
    keys = _load("mcp_api_keys.json")
    sessions = _load("bsky_sessions.json")
    sgc = _load("social_graph_and_collections.json")
    if not isinstance(keys, list): keys = []
    if not isinstance(sessions, list): sessions = []
    if not isinstance(sgc, list): sgc = []

    # Resolve any active API key for quotas. list-resources does not require a session_id.
    active_keys = [k for k in keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _log_invocation(sgc, None, {}, {"error": "UNAUTHORIZED"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    sess_ids_by_key = {}
    for s in sessions:
        if not isinstance(s, dict):
            continue
        kid = s.get("api_key_id")
        sid = s.get("id")
        if isinstance(kid, str) and isinstance(sid, str):
            sess_ids_by_key.setdefault(kid, set()).add(sid)

    def _count_for_key(api_key_id):
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_start = _day_start_utc(now_dt)
        sids = sess_ids_by_key.get(api_key_id, set())
        cnt_min = 0
        cnt_day = 0
        for r in sgc:
            if not isinstance(r, dict) or r.get("row_type") != "tool_invocation":
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            sid = r.get("session_id")
            if sid is None:
                continue
            if sid not in sids:
                continue
            if ts >= minute_ago: cnt_min += 1
            if ts >= day_start: cnt_day += 1
        return cnt_min, cnt_day

    chosen_key = None
    for k in active_keys:
        qpm = k.get("quota_requests_per_minute")
        qpd = k.get("quota_requests_per_day")
        if not isinstance(qpm, int) or not isinstance(qpd, int):
            continue
        cnt_min, cnt_day = _count_for_key(k.get("id"))
        if cnt_min < qpm and cnt_day < qpd:
            chosen_key = k
            break
    if not chosen_key:
        _log_invocation(sgc, None, {}, {"error": "RATE_LIMIT"}, "deleted")
        _save("social_graph_and_collections.json", sgc)
        return _err("RATE_LIMIT", "Rate limit exceeded for available API keys.")

    resources = [
        {"name": "actors", "description": "Cached Bluesky actor profiles (actors.json)."},
        {"name": "posts", "description": "Cached Bluesky posts (posts.json)."},
        {"name": "social_graph_and_collections", "description": "Cached follows/likes/feeds/lists/trends/search/tool invocations."},
        {"name": "bsky_sessions", "description": "Cached authenticated sessions for Bluesky users."},
        {"name": "mcp_api_keys", "description": "MCP API keys and quotas."},
    ]

    latency_ms = int((time.time() - start_t) * 1000)
    _log_invocation(sgc, None, {}, {"latency_ms": latency_ms, "resources": len(resources)}, "active")
    _save("social_graph_and_collections.json", sgc)

    # update api key last_used_at
    now_iso = _iso(now_dt)
    for k in keys:
        if isinstance(k, dict) and k.get("id") == chosen_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("mcp_api_keys.json", keys)

    return {"resources": resources, "meta": {"count": len(resources), "latency_ms": latency_ms}}
